#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../asmooth-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int w=128,n=w*w,t=4000,r=5,repeat=argc>1?atoi(argv[1]):10;std::vector<float>input(n),ei,en(n,0),eo(n,0),gi(n),gn(n),go(n),expected,output;std::vector<int>eb(n,0),gb(n);srand(123);for(int i=0;i<n;i++)input[i]=rand()%256;ei=input;reference(w,w,t,r,ei.data(),eb.data(),en.data(),eo.data());expected=ei;expected.insert(expected.end(),en.begin(),en.end());for(int v:eb)expected.push_back(float(v));expected.insert(expected.end(),eo.begin(),eo.end());float *img,*norm,*out;int*box;CK(cudaMalloc(&img,n*4));CK(cudaMalloc(&norm,n*4));CK(cudaMalloc(&out,n*4));CK(cudaMalloc(&box,n*4));auto reset=[&](){CK(cudaMemcpy(img,input.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemset(norm,0,n*4));CK(cudaMemset(out,0,n*4));CK(cudaMemset(box,0,n*4));CK(cudaDeviceSynchronize());};auto launch=[&](){smoothingFilter<<<dim3(8,8),dim3(16,16)>>>(w,w,t,r,img,box,norm);normalizeFilter<<<dim3(8,8),dim3(16,16)>>>(w,w,img,norm);outFilter<<<dim3(8,8),dim3(16,16)>>>(w,w,img,box,out);};reset();launch();CK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){double elapsed=0;for(int rep=0;rep<repeat;rep++){reset();auto t0=std::chrono::steady_clock::now();launch();CK(cudaDeviceSynchronize());elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;}CK(cudaMemcpy(gi.data(),img,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(gn.data(),norm,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(go.data(),out,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(gb.data(),box,n*4,cudaMemcpyDeviceToHost));output=gi;output.insert(output.end(),gn.begin(),gn.end());for(int v:gb)output.push_back(float(v));output.insert(output.end(),go.begin(),go.end());float ma=0,mr=0;bool ok=gb==eb;for(int i=0;i<4*n;i++){float e=fabsf(output[i]-expected[i]);ma=fmaxf(ma,e);mr=fmaxf(mr,e/fmaxf(fabsf(expected[i]),1.1920929e-7f));ok&=std::isfinite(output[i])&&e<=1e-3f;}all&=ok;char file[100];sprintf(file,"asmooth_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"box_exact\":%s,\"timing_region\":\"adaptive_box_norm_normalize_and_output_three_kernels_resets_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",4*n,ma,mr,gb==eb?"true":"false",repeat,file,4*n);}CK(cudaFree(img));CK(cudaFree(norm));CK(cudaFree(out));CK(cudaFree(box));puts(all?"PASS":"FAIL");return all?0:1;}
